import { section8Databases, section8SqlCases } from './course-v3-section8-sql.mjs';
import { orderHeaders, unnormalisedOrders, order1NF, orderRelations } from './course-v3-section8-examples.mjs';

// One authored source feeds classroom steps and complete independent reading.
// All library and shop records are invented teaching data, not past-paper data.
const ids = (requirement, ...numbers) => numbers.map(number => `S8.${String(requirement).padStart(2, '0')}.A${String(number).padStart(2, '0')}`);
const table = (headers, rows, title) => ({ headers, rows, ...(title ? { title } : {}) });
const step = (title, body, extra = {}) => ({ title, body, ...extra });
const worked = (title, setup, steps, conclusion) => ({ title, setup, steps, conclusion });
const memberTable = section8Databases.library.tables[0];
const loanTable = section8Databases.library.tables[1];
const members = table(['MemberID', 'MemberName'], memberTable.rows.map(row => row.slice(0, 2)), 'Member');
const loans = table(['LoanID', 'MemberID'], loanTable.rows.map(row => row.slice(0, 2)), 'Loan');
const result = key => table(section8SqlCases[key].headers, section8SqlCases[key].expectedRows, 'Result from the initial data');
const relation = name => ({ ...orderRelations[name], title: name === 'SalesOrder2NF' ? 'SalesOrder at 2NF' : name });

